test("enemy level option affects only attackable nameplates and restores opacity", function()
    start("visible = {MakePlate('enemy', nil, false, false), MakePlate('friend', 'Friends')}")
    eq(eval("visible[1].UnitFrame.PlayerLevelDiffFrame.alpha"), 1)
    run("visible[1].UnitFrame.PlayerLevelDiffFrame.alpha = 0.4; namespace.SetSetting('hideEnemyLevels', true)")
    eq(eval("visible[1].UnitFrame.PlayerLevelDiffFrame.alpha"), 0)
    eq(eval("visible[2].UnitFrame.PlayerLevelDiffFrame.alpha"), 1)
    run("namespace.Reset()")
    eq(eval("visible[1].UnitFrame.PlayerLevelDiffFrame.alpha"), 0.4)
end)

test("pooled level badges restore on friendly reuse and hook is registered once", function()
    start("visible = {MakePlate('enemy', nil, false)}")
    run("namespace.SetSetting('hideEnemyLevels', true); namespace.Refresh(); namespace.Refresh()")
    eq(eval("hookCalls"), 1)
    eq(eval("visible[1].UnitFrame.PlayerLevelDiffFrame.alpha"), 0)
    run("enemies.enemy = false; CompactUnitFrame_UpdatePlayerLevelDiff(visible[1].UnitFrame)")
    eq(eval("visible[1].UnitFrame.PlayerLevelDiffFrame.alpha"), 1)
end)

test("enemy badge checkbox is independent from guild visibility and context pauses", function()
    start("visible = {MakePlate('enemy', nil, false)}; combat = true; instance = true")
    run("namespace.ShowSettings(); namespace.SettingsWindow.hideEnemyLevels:SetChecked(true); namespace.SettingsWindow.hideEnemyLevels.scripts.OnClick(namespace.SettingsWindow.hideEnemyLevels)")
    eq(eval("visible[1].UnitFrame.PlayerLevelDiffFrame.alpha"), 0)
    run("namespace.SetSetting('enabled', false)")
    eq(eval("visible[1].UnitFrame.PlayerLevelDiffFrame.alpha"), 0)
    run("namespace.SetSetting('hideEnemyLevels', false)")
    eq(eval("visible[1].UnitFrame.PlayerLevelDiffFrame.alpha"), 1)
end)

test("forbidden badges and secret attackability are skipped", function()
    start("visible = {MakePlate('enemy', nil, false)}")
    run("visible[1].UnitFrame.PlayerLevelDiffFrame.IsForbidden = function() return true end; namespace.SetSetting('hideEnemyLevels', true)")
    eq(eval("visible[1].UnitFrame.PlayerLevelDiffFrame.alpha"), 1)
    run("visible[1].UnitFrame.PlayerLevelDiffFrame.IsForbidden = function() return false end; secret = {}; issecretvalue = function(value) return rawequal(value, secret) end; enemies.enemy = secret; namespace.Refresh()")
    eq(eval("visible[1].UnitFrame.PlayerLevelDiffFrame.alpha"), 1)
end)

test("removing one moving plate does not hide another player's guild", function()
