    run("driver.scripts.OnEvent(driver, 'NAME_PLATE_UNIT_REMOVED', 'two')")
    eq(eval("labels[1].shown"), true)
    eq(eval("labels[2].shown"), false)
end)

test("ordinary refreshes never hide a valid visible guild label", function()
