    run("originalAnchor = labels[1].anchor; namespace.Refresh(); namespace.Refresh(); timer.callback()")
    eq(eval("labels[1].hideCalls"), nil)
    eq(eval("labels[1].anchor == originalAnchor"), true)
    eq(eval("labels[1].shown"), true)
