end)

test("brief missing guild data is retained but expires and recovers", function()
    start()
    run("guilds.nameplate1 = nil; clock = 1; namespace.Refresh()")
    eq(eval("labels[1].shown"), true)
    eq(eval("labels[1].text"), "<Azeroth Explorers>")
    run("clock = 3; namespace.Refresh()")
    eq(eval("labels[1].shown"), false)
    run("guilds.nameplate1 = 'Back Again'; namespace.Refresh()")
    eq(eval("labels[1].shown"), true)
    eq(eval("labels[1].text"), "<Back Again>")
end)

